/* ---------- amount in words (Indian system) ---------- */
function numToWords(num){
  num=Math.round(Number(num)||0);
  if(num===0)return 'Zero';
  const a=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];
  const b=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];
  const two=n=>n<20?a[n]:b[Math.floor(n/10)]+(n%10?' '+a[n%10]:'');
  const three=n=>{const h=Math.floor(n/100),r=n%100;return (h?a[h]+' Hundred'+(r?' ':''):'')+(r?two(r):'');};
  let out='',crore=Math.floor(num/1e7);num%=1e7;
  const lakh=Math.floor(num/1e5);num%=1e5;
  const thousand=Math.floor(num/1e3);num%=1e3;
  if(crore)out+=three(crore)+' Crore ';
  if(lakh)out+=two(lakh)+' Lakh ';
  if(thousand)out+=two(thousand)+' Thousand ';
  if(num)out+=three(num);
  return out.trim();
}
function amountInWords(n){
  const r=Math.round((Number(n)||0)*100)/100;
  const whole=Math.floor(r),paise=Math.round((r-whole)*100);
  let s='Rupees '+numToWords(whole);
  if(paise)s+=' and '+numToWords(paise)+' Paise';
  return s+' Only';
}

/* ---------- invoice numbering ---------- */
const nextInvPreview=()=>{const k='INV_'+yr();return `ADSWISE/INV/${yr()}/${String((S.counters[k]||0)+1).padStart(3,'0')}`;};
const commitInvNo=()=>{const k='INV_'+yr();S.counters[k]=(S.counters[k]||0)+1;LS.save('counters',S.counters);return `ADSWISE/INV/${yr()}/${String(S.counters[k]).padStart(3,'0')}`;};

/* ---------- calculations ---------- */
function calc(inv){
  const items=(inv.items||[]).map(it=>({...it,amount:(+it.qty||0)*(+it.rate||0)}));
  const subtotal=items.reduce((a,i)=>a+i.amount,0);
  const discPct=+inv.discountPct||0;
  const discount=subtotal*discPct/100;
  const taxable=subtotal-discount;
  /* No GSTIN configured => tax is force-disabled everywhere (display AND totals). */
  const effType=S.settings.gst?(inv.taxType||'none'):'none';
  const rate=effType==='none'?0:(+inv.gstRate||0);
  let cgst=0,sgst=0,igst=0;
  if(effType==='intra'){cgst=taxable*rate/200;sgst=taxable*rate/200;}
  else if(effType==='inter'){igst=taxable*rate/100;}
  const pre=taxable+cgst+sgst+igst;
  const grand=Math.round(pre);
  const roundOff=grand-pre;
  const advance=+inv.advance||0;
  const balance=Math.max(0,grand-advance);
  return {items,subtotal,discPct,discount,taxable,rate,cgst,sgst,igst,pre,roundOff,grand,advance,balance,effType};
}
const isOverdue=inv=>{const c=calc(inv);return inv.due && inv.due<todayISO() && c.balance>0 && !['Paid','Cancelled'].includes(inv.status);};
const dispStatus=inv=>isOverdue(inv)&&inv.status!=='Overdue'?'Overdue':(inv.status||'Draft');

