/* ============ DASHBOARD ============ */
let charts={};
function metrics(){
  const inv=S.invoices.filter(i=>i.status!=='Cancelled');
  const tot=inv.reduce((a,i)=>a+calc(i).grand,0);
  const recv=inv.reduce((a,i)=>a+calc(i).advance,0);
  const out=inv.reduce((a,i)=>a+calc(i).balance,0);
  const paid=inv.filter(i=>i.status==='Paid');
  const pend=inv.filter(i=>['Sent','Pending','Partially Paid','Draft'].includes(i.status)&&!isOverdue(i));
  const over=inv.filter(isOverdue);
  const m=new Date().getMonth(),y=yr();
  const mRev=inv.filter(i=>{const d=new Date(i.date);return d.getMonth()===m&&d.getFullYear()===y;}).reduce((a,i)=>a+calc(i).grand,0);
  const yRev=inv.filter(i=>new Date(i.date).getFullYear()===y).reduce((a,i)=>a+calc(i).grand,0);
  return {tot,recv,out,paidN:paid.length,pendN:pend.length,overN:over.length,clientsN:S.clients.length,mRev,yRev};
}
