function drawCharts(){
  if(typeof Chart==='undefined')return;
  Object.values(charts).forEach(c=>{try{c.destroy()}catch(e){}});
  const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const data=Array(12).fill(0);
  S.invoices.filter(i=>i.status!=='Cancelled'&&new Date(i.date).getFullYear()===yr())
    .forEach(i=>{data[new Date(i.date).getMonth()]+=calc(i).grand;});
  const css=getComputedStyle(document.documentElement);
  const navy=css.getPropertyValue('--navy').trim()||'#0F2B5B',gold=css.getPropertyValue('--gold').trim()||'#C9A24D';
  const tick=css.getPropertyValue('--muted').trim();
  try{
    charts.m=new Chart(document.getElementById('chMonth'),{type:'bar',
      data:{labels:months,datasets:[{data,backgroundColor:gold,borderRadius:5}]},
      options:{plugins:{legend:{display:false}},maintainAspectRatio:false,
        scales:{y:{ticks:{color:tick,callback:v=>'₹'+(v>=1e5?(v/1e5)+'L':v/1000+'k')},grid:{color:'rgba(128,128,128,.12)'}},x:{ticks:{color:tick},grid:{display:false}}}}});
    const sc={};S.invoices.forEach(i=>{const s=dispStatus(i);sc[s]=(sc[s]||0)+1;});
    const labels=Object.keys(sc);
    charts.s=new Chart(document.getElementById('chStatus'),{type:'doughnut',
      data:{labels,datasets:[{data:labels.map(l=>sc[l]),
        backgroundColor:labels.map(l=>({Paid:'#1f9d63',Overdue:'#c0392b','Partially Paid':'#b88314',Draft:'#9aa3b5',Sent:'#2563eb',Pending:'#2563eb',Cancelled:'#6b7280'}[l]||navy))}]},
      options:{maintainAspectRatio:false,plugins:{legend:{position:'right',labels:{color:tick,boxWidth:12,font:{size:11}}}}}});
  }catch(e){}
}

